import { NextResponse } from "next/server";
import { auth } from "@clerk/nextjs/server";
import { checkRateLimit, rateLimitHeaders, RateLimits } from "@/lib/rate-limit";
import { logger } from "@/lib/utils";

const BACKEND_URL = process.env.API_URL || process.env.NEXT_PUBLIC_API_URL;

export async function GET() {
  try {
    const { userId, getToken } = await auth();
    if (!userId) {
      return NextResponse.json({ error: "Unauthorized" }, { status: 401 });
    }

    const rateLimit = checkRateLimit(`learning:patterns:${userId}`, RateLimits.standard);
    if (!rateLimit.success) {
      return NextResponse.json(
        { error: "Rate limit exceeded" },
        { status: 429, headers: rateLimitHeaders(rateLimit) }
      );
    }

    const token = await getToken();
    if (!token) {
      return NextResponse.json({ error: "Authentication error" }, { status: 401 });
    }

    const response = await fetch(`${BACKEND_URL}/v1/learning/patterns`, {
      headers: {
        Authorization: `Bearer ${token}`,
        "Content-Type": "application/json",
      },
      cache: "no-store",
    });

    if (!response.ok) {
      const errorText = await response.text();
      logger.error("Backend error fetching learning patterns", {
        status: response.status,
        error: errorText,
      });
      return NextResponse.json(
        { error: "Failed to fetch learning patterns" },
        { status: response.status }
      );
    }

    const data = await response.json();
    return NextResponse.json(data);
  } catch (error) {
    logger.error("Error fetching learning patterns", { error });
    return NextResponse.json({ error: "Internal server error" }, { status: 500 });
  }
}

